// Generates supabase/functions/_shared/spec-bundle.ts from spec/ and the sample story, so the Edge
// Function (which can only bundle files under supabase/functions/) ships the same spec as the app.
// Run with `pnpm spec:bundle` after editing anything in spec/. A unit test fails if it's stale.
import { readFileSync, writeFileSync } from 'node:fs'

export function buildSpecBundle() {
  const read = (p) => readFileSync(p, 'utf8')
  const json = (p) => JSON.stringify(JSON.parse(read(p)))
  return [
    '// Generated by scripts/gen-spec-bundle.mjs from spec/ and stories/the-silent-light. Do not edit.',
    `export const STORY_FORMAT_MD: string = ${JSON.stringify(read('spec/STORY_FORMAT.md'))}`,
    `export const STORY_SCHEMA: Record<string, unknown> = ${json('spec/story.schema.json')}`,
    'export interface LibrarySound { id: string; status?: string; tags?: string[]; [key: string]: unknown }',
    `export const SOUNDS: { ambience: LibrarySound[]; sfx: LibrarySound[]; [key: string]: unknown } = ${json('spec/sounds.json')}`,
    `export const SAMPLE_STORY: Record<string, unknown> = ${json('stories/the-silent-light/story.json')}`,
    '',
  ].join('\n')
}

if (process.argv[1]?.endsWith('gen-spec-bundle.mjs')) {
  writeFileSync('supabase/functions/_shared/spec-bundle.ts', buildSpecBundle())
  console.log('spec-bundle.ts written')
}
